// Architectural drawings generated from a unit's data (pure string builders, no DOM).
// - elevation(): the building's street facade with the unit's floor marked. Used as a lazy <img>
//   on cards (files generated by scripts/build.mjs) and inline in the hero.
// - floorPlan(): an indicative plan from rooms / baths / size, used inline on the unit page.
// They stand in for photos in this demo; a real office adds its own photos next to them.

const INK = "#22282B";
const PAPER = "#FFFFFF";
const TINT = { sale: "#F4D9D5", rent: "#D3E8E9" };

/** Small deterministic PRNG so every unit always gets the same drawing. */
export function seeded(id) {
  let h = 2166136261;
  for (const ch of String(id)) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
  return () => {
    h = Math.imul(h ^ (h >>> 15), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    return ((h ^= h >>> 16) >>> 0) / 4294967296;
  };
}

const r1 = (n) => Math.round(n * 10) / 10;

/** Floors that belong to the unit (a duplex takes two). */
export function unitFloors(unit) {
  return unit.type === "duplex" ? [unit.floor, Math.min(unit.floor + 1, unit.floors)] : [unit.floor];
}

export function elevationLayout(unit) {
  const rand = seeded(unit.id);
  const floors = Math.max(1, Math.min(unit.floors, 13));
  const bays = unit.type === "chalet" ? 4 : unit.size >= 200 ? 4 : 3;
  const floorH = unit.type === "chalet" ? 30 : 20;
  const W = 280, side = 22, bw = (W - side * 2) / bays;
  const roofH = 30, groundH = unit.type === "chalet" ? 26 : 30, base = 16;
  const H = roofH + floors * floorH + groundH + base;
  const groundTop = roofH + floors * floorH;
  const floorTop = (n) => groundTop - n * floorH; // n = 1 is the first floor above ground
  const balconyBay = Math.floor(bays / 2) - (bays % 2 === 0 && rand() > 0.5 ? 1 : 0);
  return { rand, floors, bays, floorH, W, H, side, bw, roofH, groundH, base, groundTop, floorTop, balconyBay };
}

/** Facade SVG + where the "for sale" banner hangs (percent of the drawing). */
export function elevation(unit, { animate = false } = {}) {
  const L = elevationLayout(unit);
  const { rand, floors, bays, floorH, W, H, side, bw, roofH, groundTop, floorTop, balconyBay } = L;
  const mine = unitFloors(unit);
  const s = [];
  const rect = (x, y, w, h, extra = "") => s.push(`<rect x="${r1(x)}" y="${r1(y)}" width="${r1(w)}" height="${r1(h)}" ${extra}/>`);

  // Body of the building.
  rect(side, roofH, W - side * 2, floors * floorH + L.groundH, `fill="${PAPER}" stroke-width="1.6"`);
  // Unit floors tinted.
  for (const n of mine) rect(side, floorTop(n), W - side * 2, floorH, `fill="${TINT[unit.purpose]}" stroke="none"`);
  // Floor slabs.
  for (let n = 1; n <= floors; n++) s.push(`<path d="M${side} ${r1(floorTop(n) + floorH)}H${W - side}" stroke-width="0.8"/>`);

  // Windows with louvred shutters, balconies, the odd split-AC unit.
  for (let n = 1; n <= floors; n++) {
    const y = floorTop(n);
    for (let b = 0; b < bays; b++) {
      const cx = side + bw * b + bw / 2;
      const ww = bw * (b === balconyBay ? 0.5 : 0.38), wh = floorH * 0.62, wx = cx - ww / 2, wy = y + floorH * 0.17;
      rect(wx, wy, ww, wh, `fill="${PAPER}" stroke-width="0.9"`);
      for (let k = 1; k < 4; k++) s.push(`<path d="M${r1(wx + 1.5)} ${r1(wy + (wh * k) / 4)}H${r1(wx + ww - 1.5)}" stroke-width="0.4"/>`);
      s.push(`<path d="M${r1(cx)} ${r1(wy)}V${r1(wy + wh)}" stroke-width="0.5"/>`);
      if (b === balconyBay) {
        const bx = cx - bw * 0.36, by = y + floorH * 0.62, bwid = bw * 0.72, bh = floorH * 0.38;
        rect(bx, by, bwid, bh, `fill="${PAPER}" stroke-width="1"`);
        for (let k = 1; k < 9; k++) s.push(`<path d="M${r1(bx + (bwid * k) / 9)} ${r1(by + 1)}V${r1(by + bh)}" stroke-width="0.35"/>`);
      } else if (rand() < 0.28) {
        const ax = b < balconyBay ? wx - 9 : wx + ww + 2;
        rect(ax, wy + wh - 7, 7, 6, `fill="${PAPER}" stroke-width="0.6"`);
        s.push(`<circle cx="${r1(ax + 3.5)}" cy="${r1(wy + wh - 4)}" r="1.8" fill="none" stroke-width="0.4"/>`);
      }
    }
  }

  // Ground floor: shop shutters and the entrance.
  const entranceBay = bays % 2 ? Math.floor(bays / 2) : balconyBay + 1;
  for (let b = 0; b < bays; b++) {
    const x = side + bw * b + bw * 0.1, w = bw * 0.8, y = groundTop + 6, h = L.groundH - 6;
    if (b === entranceBay) {
      const cx = x + w / 2, dw = w * 0.5;
      s.push(`<path d="M${r1(cx - dw / 2)} ${r1(y + h)}V${r1(y + dw / 2)}A${r1(dw / 2)} ${r1(dw / 2)} 0 0 1 ${r1(cx + dw / 2)} ${r1(y + dw / 2)}V${r1(y + h)}" fill="${PAPER}" stroke-width="1"/>`);
      s.push(`<path d="M${r1(cx)} ${r1(y + 2)}V${r1(y + h)}" stroke-width="0.5"/>`);
    } else if (unit.type !== "chalet") {
      rect(x, y, w, h, `fill="${PAPER}" stroke-width="0.9"`);
      for (let k = 1; k < 7; k++) s.push(`<path d="M${r1(x)} ${r1(y + (h * k) / 7)}H${r1(x + w)}" stroke-width="0.35"/>`);
    } else {
      rect(x + w * 0.2, y + 2, w * 0.6, h * 0.6, `fill="${PAPER}" stroke-width="0.8"`);
    }
  }

  // Roof: parapet, stair room, water tanks, a satellite dish or two.
  s.push(`<path d="M${side - 3} ${roofH}H${W - side + 3}" stroke-width="2.2"/>`);
  if (unit.type === "roof") {
    const tx = side + 4, tw = (W - side * 2) * 0.55;
    rect(tx, roofH - 8, tw, 8, `fill="${TINT[unit.purpose]}" stroke-width="0.9"`);
    for (let k = 1; k < 14; k++) s.push(`<path d="M${r1(tx + (tw * k) / 14)} ${roofH - 8}V${roofH}" stroke-width="0.35"/>`);
  }
  const stairX = side + (W - side * 2) * (0.62 + rand() * 0.1);
  rect(stairX, roofH - 16, 30, 16, `fill="${PAPER}" stroke-width="1"`);
  const tanks = 1 + Math.floor(rand() * 3);
  for (let t = 0; t < tanks; t++) {
    const tx = stairX + 34 + t * 13;
    if (tx + 10 > W - side) break;
    s.push(`<path d="M${r1(tx)} ${roofH}V${roofH - 12}H${r1(tx + 10)}V${roofH}" fill="${PAPER}" stroke-width="0.9"/><ellipse cx="${r1(tx + 5)}" cy="${roofH - 12}" rx="5" ry="1.6" fill="${PAPER}" stroke-width="0.7"/>`);
  }
  const dishX = side + 10 + rand() * 50;
  if (unit.type !== "roof") s.push(`<path d="M${r1(dishX)} ${roofH}V${roofH - 7}" stroke-width="0.7"/><path d="M${r1(dishX - 6)} ${roofH - 13}A7 7 0 0 0 ${r1(dishX + 4)} ${roofH - 5}Z" fill="${PAPER}" stroke-width="0.8"/>`);

  // Pavement.
  s.push(`<path d="M4 ${H - L.base}H${W - 4}" stroke-width="2"/>`);
  for (let x = 8; x < W - 6; x += 7) s.push(`<path d="M${x} ${H - L.base + 2}l-5 6" stroke-width="0.4"/>`);

  const topFloor = Math.max(...mine);
  const bannerX = ((side + bw * balconyBay + bw / 2) / W) * 100;
  const bannerY = ((floorTop(topFloor) + floorH * 0.62) / H) * 100;
  const cls = animate ? ` class="draw"` : "";
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" fill="none" stroke="${INK}" stroke-linecap="square"${cls} role="img" aria-label="واجهة العمارة، الدور ${unit.floor} من ${unit.floors}">${s.join("")}</svg>`;
  return { svg, width: W, height: H, bannerX: r1(bannerX), bannerY: r1(bannerY) };
}

/** Rooms for an indicative plan. Areas are net (about 88% of the listed size). */
export function planRooms(unit) {
  const net = unit.size * 0.88;
  const W = 360, Hh = 250;
  const rooms = [];
  const colA = unit.rooms === 1 ? W * 0.62 : W * 0.56;
  const add = (name, x, y, w, h, kind) => rooms.push({ name, x, y, w, h, kind, m2: Math.max(2, Math.round((w * h) / (W * Hh) * net)) });

  if (unit.rooms === 1) {
    add("معيشة ونوم", 0, 0, colA, Hh, "living");
    add("مطبخ", colA, 0, W - colA, Hh * 0.55, "kitchen");
    add("حمام", colA, Hh * 0.55, W - colA, Hh * 0.45, "bath");
    return { W, H: Hh, rooms };
  }
  const recH = Hh * 0.64;
  add("ريسبشن", 0, 0, colA, recH, "living");
  if (unit.baths >= 2) {
    add("مطبخ", 0, recH, colA * 0.62, Hh - recH, "kitchen");
    add(colA * 0.38 > 95 ? "حمام ضيوف" : "حمام", colA * 0.62, recH, colA * 0.38, Hh - recH, "bath");
  } else {
    add("مطبخ", 0, recH, colA, Hh - recH, "kitchen");
  }
  const bathsB = unit.baths >= 2 ? unit.baths - 1 : unit.baths;
  const bathH = Hh * 0.17;
  const bedH = (Hh - bathH * bathsB) / unit.rooms;
  let y = 0;
  for (let i = 0; i < unit.rooms; i++) {
    const master = i === 0 && unit.baths >= 2;
    add(master ? "نوم ماستر" : `غرفة نوم ${"١٢٣٤٥"[i]}`, colA, y, W - colA, bedH, "bed");
    y += bedH;
    if (i < bathsB) {
      add("حمام", colA, y, W - colA, bathH, "bath");
      y += bathH;
    }
  }
  return { W, H: Hh, rooms };
}

const COMPASS_ROT = { "بحري": 0, "قبلي": 180, "شرقي": -90, "غربي": 90 };

export function floorPlan(unit) {
  const { W, H, rooms } = planRooms(unit);
  const pad = 34, VW = W + pad * 2, VH = H + pad * 2 + 30;
  const rand = seeded(unit.id + "plan");
  const s = [];
  const X = (x) => r1(x + pad), Y = (y) => r1(y + pad);

  // Balcony outside the reception (top edge = the facing side).
  const rec = rooms[0];
  s.push(`<rect class="pl-balcony" x="${X(rec.x + rec.w * 0.2)}" y="${Y(-16)}" width="${r1(rec.w * 0.6)}" height="16"/>`);
  for (let k = 1; k < 12; k++) s.push(`<path class="pl-thin" d="M${X(rec.x + rec.w * 0.2 + (rec.w * 0.6 * k) / 12)} ${Y(-16)}V${Y(0)}"/>`);

  for (const r of rooms) {
    s.push(`<rect class="pl-room pl-${r.kind}" x="${X(r.x)}" y="${Y(r.y)}" width="${r1(r.w)}" height="${r1(r.h)}"/>`);
  }
  // Doors: a gap in the wall facing the hall + a quarter swing.
  for (const r of rooms.slice(1)) {
    const d = Math.min(26, r.h * 0.5, r.w * 0.5);
    const onLeftWall = r.x > 0;
    if (onLeftWall) {
      const y0 = r.y + 6 + rand() * Math.max(0, r.h - d - 12);
      s.push(`<path class="pl-gap" d="M${X(r.x)} ${Y(y0)}V${Y(y0 + d)}"/>`);
      s.push(`<path class="pl-door" d="M${X(r.x)} ${Y(y0)}L${X(r.x + d)} ${Y(y0)}A${r1(d)} ${r1(d)} 0 0 1 ${X(r.x)} ${Y(y0 + d)}"/>`);
    } else {
      const x0 = r.x + 6 + rand() * Math.max(0, r.w - d - 12);
      s.push(`<path class="pl-gap" d="M${X(x0)} ${Y(r.y)}H${X(x0 + d)}"/>`);
      s.push(`<path class="pl-door" d="M${X(x0)} ${Y(r.y)}L${X(x0)} ${Y(r.y + d)}A${r1(d)} ${r1(d)} 0 0 0 ${X(x0 + d)} ${Y(r.y)}"/>`);
    }
  }
  s.push(`<rect class="pl-outer" x="${pad}" y="${pad}" width="${W}" height="${H}"/>`);
  // Windows on the facing wall (top) for rooms touching it.
  for (const r of rooms.filter((r) => r.y === 0 && r.kind !== "bath")) {
    const wx = r.x + r.w * 0.3, ww = r.w * 0.4;
    s.push(`<path class="pl-window" d="M${X(wx)} ${Y(-2.5)}H${X(wx + ww)}M${X(wx)} ${Y(2.5)}H${X(wx + ww)}"/>`);
  }
  for (const r of rooms) {
    const big = r.w > 90 && r.h > 70;
    s.push(`<text class="pl-label${big ? " big" : ""}" x="${X(r.x + r.w / 2)}" y="${Y(r.y + r.h / 2 - (big ? 3 : 1))}" text-anchor="middle">${r.name}</text>`);
    if (r.h > 34) s.push(`<text class="pl-m2" x="${X(r.x + r.w / 2)}" y="${Y(r.y + r.h / 2 + (big ? 15 : 12))}" text-anchor="middle">${new Intl.NumberFormat("ar-EG").format(r.m2)} م²</text>`);
  }
  // Compass: north points to the sea when the unit faces بحري.
  const rot = COMPASS_ROT[unit.facing] ?? 0;
  const cx = VW - 24, cy = VH - 22;
  s.push(`<g class="pl-compass" transform="rotate(${rot} ${cx} ${cy})"><circle cx="${cx}" cy="${cy}" r="12"/><path d="M${cx} ${cy - 12}L${cx + 4} ${cy}L${cx} ${cy + 3}L${cx - 4} ${cy}Z"/></g>`);
  s.push(`<text class="pl-north" x="${cx}" y="${cy - 17}" text-anchor="middle" transform="rotate(${rot} ${cx} ${cy})">شمال</text>`);
  // Scale bar (indicative).
  s.push(`<path class="pl-thin" d="M${pad} ${VH - 18}h60M${pad} ${VH - 22}v8M${pad + 30} ${VH - 20}v4M${pad + 60} ${VH - 22}v8"/>`);
  s.push(`<text class="pl-m2" x="${pad + 70}" y="${VH - 14}" text-anchor="end">رسم توضيحي، مش بمقياس</text>`);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${VW} ${VH}" class="plan" role="img" aria-label="رسم توضيحي لتقسيم الشقة: ${rooms.map((r) => r.name).join("، ")}">${s.join("")}</svg>`;
}
